solutions.naive:
class Solution:
    def corpFlightBookings(self, bookings: list[list[int]], n: int) -> list[int]:
        ans = [0] * n
        for first, last, seats in bookings:
            for flight in range(first - 1, last):
                ans[flight] += seats
        return ans

solutions.better:
class Solution:
    def corpFlightBookings(self, bookings: list[list[int]], n: int) -> list[int]:
        events = []
        for first, last, seats in bookings:
            events.append((first, seats))
            events.append((last + 1, -seats))
        events.sort()
        ans = [0] * n
        active = 0
        idx = 0
        for flight in range(1, n + 1):
            while idx < len(events) and events[idx][0] == flight:
                active += events[idx][1]
                idx += 1
            ans[flight - 1] = active
        return ans

solutions.optimal:
class Solution:
    def corpFlightBookings(self, bookings: list[list[int]], n: int) -> list[int]:
        diff = [0] * (n + 1)
        for first, last, seats in bookings:
            diff[first - 1] += seats
            diff[last] -= seats
        ans = [0] * n
        running = 0
        for i in range(n):
            running += diff[i]
            ans[i] = running
        return ans

